import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line != null) {int t = Integer.parseInt(line.trim());while (t-- > 0) {StringTokenizer st = new StringTokenizer(br.readLine());String m = st.nextToken();String w = st.nextToken();if (isSubsequence(m, w) || isSubsequence(w, m)) {out.println("YES");} else {out.println("NO");}}}out.flush();out.close();}private static boolean isSubsequence(String s1, String s2) {int i = 0, j = 0;while (i < s1.length() && j < s2.length()) {if (s1.charAt(i) == s2.charAt(j)) {i++;}j++;}return i == s1.length();}}